rule Suspicious_Nmap_Signature {
    meta:
        description = "Detects known Nmap packet patterns in memory or PCAP"
        author = "SOC Team"
        reference = "https://attack.mitre.org/techniques/T1046/"
        tlp = "amber"
    strings:
        $nmap_null_scan = { 00 00 00 00 00 }
        $nmap_xmas_scan = { FF FF FF }
        $nmap_syn_pattern = { ?? 02 ?? ?? ?? ?? ?? ?? 00 00 ?? ?? }
    condition:
        any of them
}

